/* ================================================================ */
enum {
  MT_W_GRASS,  /* short grass + 2 variants */
  MT_W_GRASS2,
  MT_W_GRASS3,
  MT_W_TALLGRASS,  /* wild kin roam here; top layer = front blades over the legs */
  MT_W_FLOWER_RED,  /* animated flower patches (2 frames) */
  MT_W_FLOWER_YELLOW,
  MT_W_TREE_TOP,  /* 16x32 broadleaf tree: TOP above BOTTOM */
  MT_W_TREE_BOTTOM,
  MT_W_PINE_TOP,  /* 16x32 pine tree: TOP above BOTTOM (forests; tiles side by side and stacked) */
  MT_W_PINE_BOTTOM,
  MT_W_LEDGE,  /* one-way ledge: walk DOWN onto it to hop over (grass lip above, earth face and drop below); tiles horizontally */
  MT_W_SAND,  /* lakeshore sand (+ SAND2 with a shell and pebbles) */
  MT_W_FOREST,  /* shady forest floor with moss and roots (+ variant) */
  MT_W_FOREST2,
  MT_W_REEDS,  /* lakeshore cattails; wild kin roam here like tall grass (top layer hides legs) */
  MT_W_STONE,  /* paving stones */
  MT_W_LEDGE_L,  /* left end of a LEDGE run (the drop tapers into the grass) */
  MT_W_LEDGE_R,  /* right end of a LEDGE run */
  MT_W_CLIFF,  /* rock wall with a grass lip on top; tiles horizontally (solid) */
  MT_W_CLIFF_FACE,  /* plain rock wall; stack under CLIFF for taller walls (solid) */
  MT_W_DIRT,  /* worn earth (camps, farm yards, trodden spots) */
  MT_W_MEADOW,  /* grass with clover and tiny white flowers (Whisper Meadow) */
  MT_W_SAND2,
  MT_W_TERRAIN_COUNT
};
